<?php
require_once __DIR__ . '/../../config.php';
require_once __DIR__ . '/../../includes/auth.php';

requireLogin();
if (!can_create_election($pdo)) { http_response_code(403); exit('Election creation access is required.'); }

/* The draft intentionally contains no uploaded files. Browser file inputs cannot be safely
 * serialised; they remain available until final confirmation, when create-election.php saves
 * them with the same validation and upload routines as the standard form. */
$draftKey = 'ai_election_draft';
if ($_SERVER['REQUEST_METHOD'] === 'POST' && ($_POST['action'] ?? '') === 'save_draft') {
    header('Content-Type: application/json; charset=utf-8');
    if (!verify_csrf($_POST['csrf_token'] ?? '')) { http_response_code(403); echo json_encode(['ok' => false, 'error' => 'Security validation failed.']); exit; }
    $state = json_decode($_POST['state'] ?? '{}', true);
    if (!is_array($state)) { http_response_code(422); echo json_encode(['ok' => false, 'error' => 'Invalid draft data.']); exit; }
    $_SESSION[$draftKey] = ['state' => $state, 'updated_at' => time()];
    echo json_encode(['ok' => true]); exit;
}
$draft = $_SESSION[$draftKey]['state'] ?? [];
$scan = $_SESSION['eligible_voter_scan'] ?? null;
?>
