<script>
const csrf = <?= json_encode(csrf_token()) ?>, initial = <?= json_encode($draft) ?>, initialScan = <?= json_encode($scan ? ['filename'=>$scan['filename'],'headers'=>$scan['headers'],'token'=>$scan['token'],'selected'=>$scan['selected_field'],'count'=>count($scan['rows'])] : null) ?>, subAdmin = <?= isAdmin() ? 'false' : 'true' ?>;
let step=1, roles=initial.roles||[], committee=initial.committee||[], positionCount=initial.positionCount||'', committeeChoice=initial.committeeChoice||'', logoChoice=initial.logoChoice||'', scan=initialScan;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
function alertUser(message){$('#alert').textContent=message;$('#alert').classList.add('show');window.scrollTo({top:0,behavior:'smooth'});} function clearAlert(){$('#alert').classList.remove('show');}
function escapeHtml(v){const d=document.createElement('div');d.textContent=v||'';return d.innerHTML;}
function renderRole(role,index){const type=role.type||'multiple', candidates=role.candidates||[{name:'',description:''}];return `<div class="ai-role" data-role="${index}"><div class="flex justify-between"><strong>Position ${index+1}</strong>${roles.length>1?`<button type="button" class="text-red-600 remove-role">Remove</button>`:''}</div><label class="block mt-3 text-sm font-medium">Position name<input data-key="name" value="${escapeHtml(role.name)}" class="role-name w-full mt-1 px-3 py-2 border rounded-lg"></label><div class="mt-3 flex gap-4 text-sm"><label><input type="radio" class="role-type" name="type${index}" value="yesno" ${type==='yesno'?'checked':''}> There is only one candidate / proposition</label><label><input type="radio" class="role-type" name="type${index}" value="multiple" ${type!=='yesno'?'checked':''}> There are multiple candidates</label></div><div class="candidate-editor">${candidates.map((c,i)=>renderCandidate(c,index,i,type)).join('')}</div><button type="button" class="add-candidate mt-3 text-blue-700 font-semibold ${type==='yesno'?'ai-hidden':''}">+ Add Another Candidate</button></div>`}
function renderCandidate(c,ri,ci,type){return `<div class="ai-candidate"><div class="grid md:grid-cols-3 gap-3"><input class="candidate-name px-3 py-2 border rounded-lg" value="${escapeHtml(c.name)}" placeholder="Candidate name"><input class="candidate-description px-3 py-2 border rounded-lg" value="${escapeHtml(c.description)}" placeholder="${type==='yesno'?'Short proposition description (required)':'Short description (optional)'}"><input class="candidate-image px-2 py-2 border rounded-lg" type="file" accept="image/*"></div>${ci>0?'<button type="button" class="remove-candidate text-red-600 text-sm mt-2">Remove candidate</button>':''}</div>`}
function renderRoles(){if(!roles.length)roles=[{name:'',type:'multiple',candidates:[{name:'',description:''}]}];$('#roles-editor').innerHTML=roles.map(renderRole).join('');}
function syncRoles(){roles=[...$('#roles-editor').querySelectorAll('[data-role]')].map(box=>({name:box.querySelector('.role-name').value.trim(),type:box.querySelector('.role-type:checked').value,candidates:[...box.querySelectorAll('.ai-candidate')].map(c=>({name:c.querySelector('.candidate-name').value.trim(),description:c.querySelector('.candidate-description').value.trim()}))}));}
function formRoles(){syncRoles(); return roles.map((r,i)=>`<input type="hidden" name="roles[${i}][form_index]" value="${i}"><input type="hidden" name="roles[${i}][name]" value="${escapeHtml(r.name)}"><input type="hidden" name="roles[${i}][type]" value="${r.type}">${r.candidates.map((c,j)=>`<input type="hidden" name="roles[${i}][candidates][${j}][name]" value="${escapeHtml(c.name)}"><input type="hidden" name="roles[${i}][candidates][${j}][description]" value="${escapeHtml(c.description)}">`).join('')}`).join('');}
function attachFinalRoleNames(){document.querySelectorAll('.generated-role').forEach(x=>x.remove());syncRoles();const area=document.createElement('div');area.className='generated-role';area.innerHTML=formRoles();$('#wizard-form').append(area);[...$('#roles-editor').querySelectorAll('[data-role]')].forEach((box,i)=>box.querySelectorAll('.candidate-image').forEach((file,j)=>{file.name=`roles[${i}][candidates][${j}][image]`;file.form='wizard-form';}));}
function state(){return {title:$('#title').value,organization:$('#organization').value,start:$('#start').value,end:$('#end').value,roles,committee,positionCount,committeeChoice,logoChoice};}
async function saveDraft(){syncRoles();const data=new URLSearchParams({action:'save_draft',csrf_token:csrf,state:JSON.stringify(state())});try{await fetch('ai-create-election.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:data});}catch(e){}}
function setStep(n){step=n;clearAlert();$('#welcome').classList.toggle('active',false);$('#flow').classList.remove('hidden');$$('.ai-step').forEach(x=>x.classList.toggle('active',+x.dataset.step===n));$('#step-label').textContent=n===9?'Review':'Step '+n+' of 8';$('#progress').style.width=(n===9?100:n*12.5)+'%';$('#back').classList.toggle('ai-hidden',n===1);$('#navigation').classList.toggle('ai-hidden',n===9);if(n===9)renderReview();saveDraft();}
function next(){if(step===1&&!$('#title').reportValidity())return;if(step===2&&!$('#organization').reportValidity())return;if(step===3&&!$('#start').reportValidity())return;if(step===4){if(!$('#end').reportValidity())return;if(new Date($('#end').value)<=new Date($('#start').value)){alertUser('The end date and time must be after the start date and time.');return;}}if(step===5&&!roles.length){alertUser('Add at least one position and candidate.');return;}if(step===6&&!$('#verification-field').value){alertUser('Upload, scan, and save an eligible-voters file.');return;}if(step===7&&subAdmin&&committee.length===0){alertUser('Sub-Administrators must add 1–6 Audit Committee email addresses.');return;}setStep(step+1)}
function renderReview(){syncRoles(); const r=roles.map(x=>`<li><strong>${escapeHtml(x.name)}</strong>: ${x.type==='yesno'?'Yes / No proposition — ':''}${x.candidates.map(c=>escapeHtml(c.name)).join(', ')}</li>`).join('');$('#review').innerHTML=`<div><dt>Election title</dt><dd>${escapeHtml($('#title').value)}</dd><dt>Organization</dt><dd>${escapeHtml($('#organization').value)}</dd><dt>Start</dt><dd>${escapeHtml($('#start').value.replace('T',' '))}</dd><dt>End</dt><dd>${escapeHtml($('#end').value.replace('T',' '))}</dd></div><div><dt>Positions and candidates</dt><dd><ul class="list-disc ml-5">${r}</ul></dd><dt>Eligible voters</dt><dd>${scan?scan.count+' voters · '+escapeHtml($('#verification-field').value):'Not selected'}</dd><dt>Audit Committee</dt><dd>${committee.length?committee.map(escapeHtml).join(', '):'None'}</dd><dt>Organization logo</dt><dd>${$('#logo-file').files[0]?escapeHtml($('#logo-file').files[0].name):'None'}</dd></div>`;}
function updateSummaries(){$('#roles-summary').textContent=roles.length?roles.length+' position'+(roles.length===1?'':'s')+' saved.':'No positions saved yet.';$('#voters-summary').textContent=scan&&$('#verification-field').value?scan.count+' voters scanned; verification field: '+$('#verification-field').value:'No voter file saved yet.';$('#committee-summary').textContent=committee.length?committee.length+' committee member'+(committee.length===1?'':'s')+' saved.':'';$('#logo-summary').textContent=$('#logo-file').files[0]?'Logo ready: '+$('#logo-file').files[0].name:'';}
const helpAnswers={create:'To create an election, go to the Admin Dashboard and click ‘Create Election with AI’ or ‘Host New Election’. You will be guided step by step.',voters:'During election creation, you will be asked to upload an Excel file (.xlsx) containing the list of eligible voters. After uploading, the system will scan the file and ask you to select the verification field.',find:'Click on ‘Find Election’ in the top menu, then enter the Election Code that was given to you by the organizer.',vote:'After finding the election, you will be asked to enter your verification detail (e.g. Index Number). If you are eligible, you will see the ballot. After selecting your candidates, you will receive an OTP by email to confirm your vote.',results:'Results can be viewed after the election has ended. Go to the Results section from the dashboard.',other:'I’m only able to help with questions about using the SmartVote system. Please choose one of the available options.'};
function showHelp(){clearAlert();$('#welcome').classList.remove('active');$('#flow').classList.add('hidden');$('#help').classList.add('active');}
function showWelcome(){$('#help').classList.remove('active');$('#flow').classList.add('hidden');$('#welcome').classList.add('active');}
function showHelpAnswer(answer){$('#help-answer').textContent=answer;$('#help-answer').classList.remove('ai-hidden');}
document.querySelectorAll('[data-welcome]').forEach(b=>b.onclick=()=>{if(b.dataset.welcome==='create')setStep(1);else if(b.dataset.welcome==='review')window.location.href=<?= json_encode(url('/review.php')) ?>;else showHelp();});$$('[data-help]').forEach(b=>b.onclick=()=>{const other=b.dataset.help==='other';$('#help-form').classList.toggle('ai-hidden',!other);if(other){showHelpAnswer(helpAnswers.other);$('#help-question').focus();}else showHelpAnswer(helpAnswers[b.dataset.help]);});$('#help-form').onsubmit=e=>{e.preventDefault();showHelpAnswer(helpAnswers.other);};$('#help-back').onclick=showWelcome;$('#next').onclick=next;$('#back').onclick=()=>setStep(Math.max(1,step-1));$('#edit-review').onclick=()=>setStep(1);
$$('[data-open]').forEach(b=>b.onclick=()=>{$('#'+b.dataset.open).classList.add('open');if(b.dataset.open==='roles-modal')renderRoles();});$$('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).classList.remove('open'));
$$('.position-count').forEach(b=>b.onclick=()=>{positionCount=b.dataset.count;if(positionCount==='one'&&roles.length>1)roles=roles.slice(0,1);$('#roles-modal').classList.add('open');renderRoles();});
$('#roles-editor').onclick=e=>{const box=e.target.closest('[data-role]');if(e.target.classList.contains('add-candidate')){syncRoles();roles[+box.dataset.role].candidates.push({name:'',description:''});renderRoles();}if(e.target.classList.contains('remove-role')){syncRoles();roles.splice(+box.dataset.role,1);renderRoles();}if(e.target.classList.contains('remove-candidate')){syncRoles();const r=roles[+box.dataset.role];r.candidates.splice([...box.querySelectorAll('.ai-candidate')].indexOf(e.target.closest('.ai-candidate')),1);renderRoles();}};$('#roles-editor').onchange=e=>{if(e.target.classList.contains('role-type')){syncRoles();const i=+e.target.closest('[data-role]').dataset.role; if(roles[i].type==='yesno')roles[i].candidates=roles[i].candidates.slice(0,1);renderRoles();}};$('#add-role').onclick=()=>{syncRoles();roles.push({name:'',type:'multiple',candidates:[{name:'',description:''}]});renderRoles()};
$('#scan-voters').onclick=async()=>{const file=$('#voters-file').files[0];if(!file){$('#scan-message').textContent='Choose an Excel file first.';return;}const data=new FormData();data.append('action','scan');data.append('csrf_token',csrf);data.append('eligible_voters',file);$('#scan-message').textContent='Scanning…';try{const res=await fetch('scan-voters.php',{method:'POST',body:data}),out=await res.json();if(!res.ok||!out.ok)throw Error(out.error);scan={...out,count:0};$('#scan-token').value=out.token;$('#scan-message').textContent=out.message;$('#headers').innerHTML='<p class="font-semibold mb-2">Select one verification field</p>'+out.headers.map(h=>`<label class="ai-choice mb-2"><input type="radio" name="header" value="${escapeHtml(h)}"> ${escapeHtml(h)}</label>`).join('');}catch(e){$('#scan-message').textContent=e.message;}};
$$('[data-save]').forEach(b=>b.onclick=async()=>{const id=b.dataset.save;if(id==='roles-modal'){syncRoles();if(roles.some(r=>!r.name||!r.candidates.length||r.candidates.some(c=>!c.name)||(r.type==='yesno'&&r.candidates.some(c=>!c.description)))){alertUser('Each position needs a name and candidate. A one-candidate proposition also needs a short description.');return;}}if(id==='voters-modal'){const choice=$('#headers input:checked');if(!choice){alertUser('Select a verification field.');return;}const data=new URLSearchParams({action:'select_field',csrf_token:csrf,scan_token:scan.token,verification_field:choice.value});const res=await fetch('scan-voters.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:data}),out=await res.json();if(!res.ok||!out.ok){alertUser(out.error||'Could not save verification field.');return;}$('#verification-field').value=choice.value;scan.selected=choice.value;scan.count=initialScan?.count||scan.count;}if(id==='committee-modal'){committee=[...$('#committee-editor input')].map(x=>x.value.trim().toLowerCase()).filter(Boolean);if(!committee.length||committee.length>6||committee.some(x=>!/^\S+@\S+\.\S+$/.test(x))||new Set(committee).size!==committee.length){alertUser('Enter 1–6 unique valid email addresses.');return;}}$('#'+id).classList.remove('open');updateSummaries();saveDraft();});
$$('.committee-choice').forEach(b=>b.onclick=()=>{committeeChoice=b.dataset.value;$$('.committee-choice').forEach(x=>x.classList.toggle('selected',x===b));if(committeeChoice==='yes'){$('#committee-editor').innerHTML=(committee.length?committee:['']).map(x=>`<input type="email" value="${escapeHtml(x)}" class="w-full px-3 py-2 border rounded-lg" placeholder="member@example.com">`).join('');$('#committee-modal').classList.add('open');}else{committee=[];updateSummaries();}});$('#add-committee').onclick=()=>{if($('#committee-editor input').length<6)$('#committee-editor').insertAdjacentHTML('beforeend','<input type="email" class="w-full px-3 py-2 border rounded-lg" placeholder="member@example.com">')};$$('.logo-choice').forEach(b=>b.onclick=()=>{logoChoice=b.dataset.value;$$('.logo-choice').forEach(x=>x.classList.toggle('selected',x===b));if(logoChoice==='yes')$('#logo-modal').classList.add('open');else updateSummaries();});
$('#wizard-form').onsubmit=e=>{syncRoles();if(!scan||!$('#verification-field').value){e.preventDefault();alertUser('Eligible voters must be scanned and saved before creation.');return;}if(subAdmin&&committee.length<1){e.preventDefault();alertUser('Sub-Administrators must add an Audit Committee.');return;}attachFinalRoleNames();const hold=document.createElement('div');hold.className='generated-role';hold.innerHTML=committee.map((v,i)=>`<input type="hidden" name="committee[${i}]" value="${escapeHtml(v)}">`).join('');$('#wizard-form').append(hold);};
$('#title').value=initial.title||'';$('#organization').value=initial.organization||'';$('#start').value=initial.start||'';$('#end').value=initial.end||''; if(scan&&scan.selected)$('#verification-field').value=scan.selected; updateSummaries();
</script>
